class Solution {
  public int maximumSaleItems(int[][] items, int budget) {
    int n = items.length, MAXF = 1501;
    int[] cnt = new int[MAXF];
    int minPrice = Integer.MAX_VALUE;
    for (int[] it : items) {
      cnt[it[0]]++;
      minPrice = Math.min(minPrice, it[1]);
    }
    int[] dp = new int[budget + 1];
    for (int[] it : items) {
      int free = -1;
      for (int m = it[0]; m < MAXF; m += it[0]) free += cnt[m];
      int cost = it[1], value = 1 + free;
      for (int w = budget; w >= cost; w--) dp[w] = Math.max(dp[w], dp[w - cost] + value);
    }
    int best = 0;
    for (int w = 0; w <= budget; w++) best = Math.max(best, dp[w] + (budget - w) / minPrice);
    return best;
  }
}
